<script setup lang="ts">
import {shallowRef,ref,computed,watch,onUnmounted} from 'vue';import {useApplication} from '../../application';import type {components} from '../../shared/api/generated';import type {MinutesCurrent} from '../../shared/api/minutes-saved';import type {GenerationTemplates} from '../../shared/api/minutes-generation';import {ApiError} from '../../shared/api/client';
const props=defineProps<{meetingId:string;current:MinutesCurrent;locked:boolean;editable:boolean}>();const emit=defineEmits<{begin:[];save:[operation:'MINUTES_TEMPLATE'|'MINUTES_EXCLUSIONS',fields:Record<string,unknown>];denied:[cause:unknown]}>();const app=useApplication(),settings=shallowRef<components['schemas']['SavedSettings']|null>(null),templates=shallowRef<GenerationTemplates|null>(null),template=ref(''),items=ref<{locatorId:string;category:string;reason:string|null}[]>([]),selected=ref(''),page=ref(0),error=ref('');let epoch=0,controller:AbortController|null=null;
const choices=computed(()=>props.current.sensitive.flatMap(d=>d.locatorIds.map(id=>({locatorId:id,category:d.category,key:d.category+':'+id}))).filter((v,i,all)=>all.findIndex(x=>x.key===v.key)===i));
function clear(){epoch++;controller?.abort();settings.value=null;templates.value=null;items.value=[];template.value='';selected.value='';error.value='';page.value=0;}
async function load(cursor:string|null=null){const turn=++epoch;controller?.abort();const request=new AbortController();controller=request;try{const [saved,available]=await Promise.all([app.minutesInspection.settings(props.meetingId,request.signal),app.minutesGeneration.templates(props.meetingId,cursor,request.signal)]);if(turn!==epoch)return;settings.value=saved;templates.value=available;template.value='';items.value=saved.items.map(i=>({locatorId:i.locator_id,category:i.category,reason:i.reason}));error.value='';}catch(cause){if(turn===epoch){if(cause instanceof ApiError&&[401,403].includes(cause.status)){clear();emit('denied',cause);}error.value=cause instanceof Error?cause.message:'设置暂不可用。';}}}
function add(){if(!props.editable)return;const v=choices.value.find(x=>x.key===selected.value);if(v&&!items.value.some(i=>i.locatorId===v.locatorId&&i.category===v.category))items.value=[...items.value,{locatorId:v.locatorId,category:v.category,reason:null}];}
watch(()=>[props.meetingId,app.session.current.value?.actor.enterpriseId,props.current.observation.revisionToken],clear,{flush:'sync'});onUnmounted(clear);
</script>
<template><section><h3>模板与排除项</h3><button class="btn" :disabled="locked" @click="load()">读取当前设置</button><p v-if="error" role="alert">{{error}}</p><template v-if="settings"><p>当前模板：{{settings.template?.name??'尚未设置'}}</p><button class="btn" :disabled="locked" @click="emit('begin')">开始修改设置</button><label>替换模板<select v-model="template" :disabled="!editable||locked"><option value="">请选择</option><option v-for="t in templates?.items" :key="t.revisionId" :value="t.revisionId" :disabled="!t.selectable">{{t.name}}</option></select></label><button v-if="templates?.nextCursor" class="btn" @click="load(templates.nextCursor)">更多模板</button><button class="btn" :disabled="!editable||locked||!template" @click="emit('save','MINUTES_TEMPLATE',{templateRevisionId:template})">保存模板选择</button>
 <h4>完整排除集合</h4><p>保存会提交完整集合，并使相关生成与最终确认条件重新计算。</p><ul><li v-for="(item,index) in items.slice(page*20,(page+1)*20)" :key="item.locatorId+item.category">{{item.category}} · {{item.locatorId}} <button class="btn" :disabled="!editable||locked" @click="items=items.filter((_,i)=>i!==page*20+index)">移除</button></li></ul><button v-if="page>0" class="btn" @click="page--">上一页</button><button v-if="(page+1)*20<items.length" class="btn" @click="page++">下一页</button><select v-model="selected" :disabled="!editable||locked"><option value="">从已保存的敏感来源选择</option><option v-for="choice in choices" :key="choice.key" :value="choice.key">{{choice.category}} · {{choice.locatorId}}</option></select><button class="btn" :disabled="!editable||locked||!selected" @click="add">加入排除集合</button><button class="btn" :disabled="!editable||locked||!settings.exclusionRevision" @click="emit('save','MINUTES_EXCLUSIONS',{sourceExclusionRevisionId:settings.exclusionRevision!.id,items})">保存完整排除集合</button></template></section></template>
<style scoped>button{margin:6px}label{display:block;margin:10px 0}select{max-width:100%;padding:8px}li{overflow-wrap:anywhere}button:disabled{opacity:.5}</style>
